package com.aoo.bcg.common.repair;import java.time.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
/** Short-lived least-privilege capability for temporary repair tools, credentials and deployments. */
public final class TemporaryRepairCapability{public record Grant(String grantId,String toolId,String deploymentId,String credentialFingerprint,Set<String>permissions,Instant issuedAt,Instant expiresAt){public Grant{if(grantId==null||grantId.isBlank()||toolId==null||toolId.isBlank()||deploymentId==null||deploymentId.isBlank()||credentialFingerprint==null||credentialFingerprint.isBlank()||permissions==null||permissions.isEmpty()||issuedAt==null||expiresAt==null||!expiresAt.isAfter(issuedAt))throw new IllegalArgumentException("invalid temporary repair grant");permissions=Set.copyOf(permissions);}}private final ConcurrentHashMap<String,Grant>active=new ConcurrentHashMap<>();private final Set<String>revoked=ConcurrentHashMap.newKeySet();public void issue(Grant grant,Duration maximumLifetime){Objects.requireNonNull(grant);if(Duration.between(grant.issuedAt(),grant.expiresAt()).compareTo(maximumLifetime)>0)throw new SecurityException("repair grant lifetime exceeds policy");if(active.putIfAbsent(grant.grantId(),grant)!=null||revoked.contains(grant.grantId()))throw new SecurityException("grant id cannot be reused");}public void authorize(String grantId,String toolId,String deploymentId,String credentialFingerprint,String permission,Instant now){Grant grant=active.get(grantId);if(grant==null||revoked.contains(grantId)||!now.isBefore(grant.expiresAt())||!grant.toolId().equals(toolId)||!grant.deploymentId().equals(deploymentId)||!grant.credentialFingerprint().equals(credentialFingerprint)||!grant.permissions().contains(permission))throw new SecurityException("temporary repair capability denied");}public void revoke(String grantId){revoked.add(grantId);active.remove(grantId);}public int revokeExpired(Instant now){int count=0;for(Grant grant:List.copyOf(active.values()))if(!now.isBefore(grant.expiresAt())){revoke(grant.grantId());count++;}return count;}}
